INSERT INTO libertades (id, nombre, peso) VALUES
  (1, 'Libre de hambre, sed y desnutrición', 0.2000),
  (2, 'Libre de molestias físicas y térmicas', 0.2000),
  (3, 'Libre de dolor, lesión y enfermedad', 0.3500),
