-- Criterios oficiales EBA-ICA por indicador y tipo de predio (norma 7.x y 9.x).
INSERT INTO indicador_criterios
  (indicador_id, tipo_predio, seccion, criterio_100, criterio_55, criterio_20, criterio_0)
VALUES
  (1, 'PRODUCTIVO', '7.1.1', 'El agua está disponible en bebederos, chupos, zanjas o jagüeyes y al menos el 90% de los animales tiene acceso a ella.', 'El agua está disponible y entre el 70% y el 89% de los animales tiene acceso a ella.', 'El agua está disponible y entre el 40% y el 69% de los animales tiene acceso a ella.', 'Menos del 40% de los animales tiene acceso al agua, o el agua no está disponible.'),
  (1, 'FAMILIAR', '9.1.1', 'El agua está disponible en bebederos, chupos, zanjas o jagüeyes y al menos el 90% de los animales tiene acceso a ella.', 'El agua está disponible y entre el 70% y el 89% de los animales tiene acceso a ella.', 'El agua está disponible y entre el 40% y el 69% de los animales tiene acceso a ella.', 'Menos del 40% de los animales tiene acceso al agua, o el agua no está disponible.'),
  (2, 'PRODUCTIVO', '7.1.2', 'Al menos el 90% de los animales tiene acceso a suficiente agua y esta es de buena calidad.', 'Entre el 70% y el 89% de los animales tiene acceso a suficiente agua de buena calidad.', 'Entre el 40% y el 69% de los animales tiene acceso a suficiente agua de buena calidad, o más del 69% tiene agua suficiente pero de mala calidad.', 'Menos del 40% de los animales tiene acceso a suficiente agua, o entre el 40% y el 69% tiene agua suficiente pero de mala calidad.'),
  (2, 'FAMILIAR', '9.1.2', 'Al menos el 90% de los animales tiene acceso a suficiente agua y esta es de buena calidad.', 'Entre el 70% y el 89% de los animales tiene acceso a suficiente agua de buena calidad.', 'Entre el 40% y el 69% de los animales tiene acceso a suficiente agua de buena calidad, o más del 69% tiene agua suficiente pero de mala calidad.', 'Menos del 40% de los animales tiene acceso a suficiente agua, o entre el 40% y el 69% tiene agua suficiente pero de mala calidad.'),
  (3, 'PRODUCTIVO', '7.1.3', 'El 90% o más de los bebederos está en buen estado, limpio y libre de moho y heces en el interior.', 'Entre el 70% y el 89% de los bebederos está en buen estado y limpio, o el predio no usa bebederos ni chupos pero garantiza el acceso al agua.', 'Entre el 40% y el 69% de los bebederos está en buen estado, limpio y libre de moho y heces en el interior.', 'Menos del 40% de los bebederos está en buen estado, o se evidencia suciedad, moho o heces en el interior.'),
  (3, 'FAMILIAR', '9.1.3', 'El 90% o más de los bebederos está en buen estado, limpio y libre de moho y heces en el interior.', 'Entre el 70% y el 89% de los bebederos está en buen estado y limpio, o el predio no usa bebederos ni chupos pero garantiza el acceso al agua.', 'Entre el 40% y el 69% de los bebederos está en buen estado, limpio y libre de moho y heces en el interior.', 'Menos del 40% de los bebederos está en buen estado, o se evidencia suciedad, moho o heces en el interior.'),
  (4, 'PRODUCTIVO', '7.1.4', 'El alimento está disponible en corrales y praderas y al menos el 90% de los animales tiene acceso a él.', 'El alimento está disponible y entre el 70% y el 89% de los animales tiene acceso a él.', 'El alimento está disponible y entre el 40% y el 69% de los animales tiene acceso a él.', 'Menos del 40% de los animales tiene acceso al alimento, o el alimento no está disponible.'),
  (4, 'FAMILIAR', '9.1.4', 'El alimento está disponible en corrales y praderas y al menos el 90% de los animales tiene acceso a él.', 'El alimento está disponible y entre el 70% y el 89% de los animales tiene acceso a él.', 'El alimento está disponible y entre el 40% y el 69% de los animales tiene acceso a él.', 'Menos del 40% de los animales tiene acceso al alimento, o el alimento no está disponible.'),
  (5, 'PRODUCTIVO', '7.1.5', 'El 90% o más de los animales tiene suficiente alimento en comederos y praderas, el alimento de los comederos es de buena calidad y se cumplen las medidas de comederos (mínimo 30 cm lineales por animal adulto y 20 cm por cordero o cabrito).', 'Entre el 70% y el 89% de los animales tiene suficiente alimento y este es de buena calidad, o no se cumplen las medidas de comederos.', 'Entre el 40% y el 69% de los animales tiene suficiente alimento, de buena calidad, y se cumplen las medidas de comederos.', 'Menos del 40% de los animales tiene suficiente alimento, o el alimento ofrecido en comederos no es de buena calidad.'),
  (5, 'FAMILIAR', '9.1.5', 'El 90% o más de los animales tiene suficiente alimento en comederos y praderas, el alimento de los comederos es de buena calidad y se cumplen las medidas de comederos (mínimo 30 cm lineales por animal adulto y 20 cm por cordero o cabrito).', 'Entre el 70% y el 89% de los animales tiene suficiente alimento y este es de buena calidad, o no se cumplen las medidas de comederos.', 'Entre el 40% y el 69% de los animales tiene suficiente alimento, de buena calidad, y se cumplen las medidas de comederos.', 'Menos del 40% de los animales tiene suficiente alimento, o el alimento ofrecido en comederos no es de buena calidad.'),
  (6, 'PRODUCTIVO', '7.1.6', 'Más del 90% de los comederos está en buen estado y limpio (sin moho, lama ni heces en el interior), o todos los animales se alimentan exclusivamente en pastoreo.', 'Entre el 70% y el 89% de los comederos está en buen estado y limpio, libre de moho, lama y heces en el interior.', 'Entre el 40% y el 69% de los comederos está en buen estado y limpio, libre de moho, lama y heces en el interior.', 'Menos del 40% de los comederos está en buen estado, o se evidencia moho, lama o heces en el interior.'),
  (6, 'FAMILIAR', '9.1.6', 'Más del 90% de los comederos está en buen estado y limpio (sin moho, lama ni heces en el interior), o todos los animales se alimentan exclusivamente en pastoreo.', 'Entre el 70% y el 89% de los comederos está en buen estado y limpio, libre de moho, lama y heces en el interior.', 'Entre el 40% y el 69% de los comederos está en buen estado y limpio, libre de moho, lama y heces en el interior.', 'Menos del 40% de los comederos está en buen estado, o se evidencia moho, lama o heces en el interior.'),
  (7, 'PRODUCTIVO', '7.1.7', 'Los alimentos y suplementos comerciales están almacenados correctamente (estibas, separados de las paredes, con aireación y sin evidencia de roedores o plagas) y cuentan con registro ICA.', 'No definido en la norma para este indicador.', 'No definido en la norma para este indicador.', 'Los alimentos y suplementos no están almacenados correctamente o no cuentan con registro ICA.'),
  (8, 'PRODUCTIVO', '7.1.8', 'Más del 80% de los animales tiene puntuación de 3 o 4 en la escala de condición corporal de 1 a 5.', 'Entre el 61% y el 80% de los animales tiene puntuación de 3 o 4.', 'Entre el 41% y el 60% de los animales tiene puntuación de 3 o 4.', 'El 40% o menos de los animales tiene puntuación de 3 o 4.'),
  (8, 'FAMILIAR', '9.1.7', 'Más del 80% de los animales tiene puntuación de 3 o 4 en la escala de condición corporal de 1 a 5.', 'Entre el 61% y el 80% de los animales tiene puntuación de 3 o 4.', 'Entre el 41% y el 60% de los animales tiene puntuación de 3 o 4.', 'El 40% o menos de los animales tiene puntuación de 3 o 4.'),
  (9, 'PRODUCTIVO', '7.2.1', 'Menos del 10% de los animales observados presenta signos de estrés térmico.', 'Entre el 10% y el 20% de los animales observados presenta signos de estrés térmico.', 'Entre el 21% y el 30% de los animales observados presenta signos de estrés térmico.', 'Más del 30% de los animales observados presenta signos de estrés térmico.'),
  (9, 'FAMILIAR', '9.2.1', 'Menos del 10% de los animales observados presenta signos de estrés térmico.', 'Entre el 10% y el 20% de los animales observados presenta signos de estrés térmico.', 'Entre el 21% y el 30% de los animales observados presenta signos de estrés térmico.', 'Más del 30% de los animales observados presenta signos de estrés térmico.'),
  (10, 'PRODUCTIVO', '7.2.2', 'Más del 90% de los animales tiene acceso a sombra en corrales y potreros.', 'Entre el 70% y el 89% de los animales tiene acceso a sombra en corrales y potreros.', 'Entre el 40% y el 69% de los animales tiene acceso a sombra en corrales y potreros.', 'Menos del 40% de los animales tiene acceso a sombra en corrales y potreros.'),
  (10, 'FAMILIAR', '9.2.2', 'Más del 90% de los animales tiene acceso a sombra en corrales y potreros.', 'Entre el 70% y el 89% de los animales tiene acceso a sombra en corrales y potreros.', 'Entre el 40% y el 69% de los animales tiene acceso a sombra en corrales y potreros.', 'Menos del 40% de los animales tiene acceso a sombra en corrales y potreros.'),
  (11, 'PRODUCTIVO', '7.2.3', 'Hay encharcamientos en menos del 10% de los corrales o potreros y existen suficientes zonas de descanso sin encharcamiento.', 'Hay encharcamientos entre el 10% y el 20% de los corrales o potreros y existen suficientes zonas de descanso sin encharcamiento.', 'Hay encharcamientos entre el 21% y el 30% de los corrales o potreros y existen zonas de descanso sin encharcamiento.', 'Hay encharcamientos en más del 30% de los corrales o potreros y no existen zonas de descanso.'),
  (11, 'FAMILIAR', '9.2.3', 'Hay encharcamientos en menos del 10% de los corrales o potreros y existen suficientes zonas de descanso sin encharcamiento.', 'Hay encharcamientos entre el 10% y el 20% de los corrales o potreros y existen suficientes zonas de descanso sin encharcamiento.', 'Hay encharcamientos entre el 21% y el 30% de los corrales o potreros y existen zonas de descanso sin encharcamiento.', 'Hay encharcamientos en más del 30% de los corrales o potreros y no existen zonas de descanso.'),
  (12, 'PRODUCTIVO', '7.2.4', 'Más del 90% de los espacios revisados cumple o supera los mínimos de espacio por animal establecidos en la norma.', 'Entre el 70% y el 89% de los espacios revisados cumple o supera los mínimos establecidos.', 'Entre el 40% y el 69% de los espacios revisados cumple o supera los mínimos establecidos.', 'Menos del 40% de los espacios revisados cumple los mínimos establecidos.'),
  (12, 'FAMILIAR', '9.2.4', 'Más del 90% de los espacios revisados cumple o supera los mínimos de espacio por animal establecidos en la norma.', 'Entre el 70% y el 89% de los espacios revisados cumple o supera los mínimos establecidos.', 'Entre el 40% y el 69% de los espacios revisados cumple o supera los mínimos establecidos.', 'Menos del 40% de los espacios revisados cumple los mínimos establecidos.'),
  (13, 'PRODUCTIVO', '7.2.5', 'En el 100% de los corrales el piso no presenta riesgo ni causa lesiones, está en buen estado y limpio, sin acumulación de residuos ni materiales extraños.', 'En entre el 70% y el 99% de los corrales el piso cumple esas condiciones (sin riesgo, buen estado, limpio y sin residuos ni materiales extraños).', 'En entre el 40% y el 69% de los corrales el piso cumple esas condiciones.', 'En menos del 40% de los corrales el piso cumple esas condiciones.'),
  (13, 'FAMILIAR', '9.2.5', 'En el 100% de los corrales el piso no presenta riesgo ni causa lesiones, está en buen estado y limpio, sin acumulación de residuos ni materiales extraños.', 'En entre el 70% y el 99% de los corrales el piso cumple esas condiciones (sin riesgo, buen estado, limpio y sin residuos ni materiales extraños).', 'En entre el 40% y el 69% de los corrales el piso cumple esas condiciones.', 'En menos del 40% de los corrales el piso cumple esas condiciones.'),
  (14, 'PRODUCTIVO', '7.2.6', 'El 100% de las camas revisadas es suave, tiene suficiente material, no deja ver el suelo, es de fácil limpieza y desinfección, no tiene elementos que lesionen a los animales y no huele a amoniaco.', 'Entre el 70% y el 99% de las camas revisadas cumple esas condiciones.', 'Entre el 40% y el 69% de las camas revisadas cumple esas condiciones.', 'Menos del 40% de las camas revisadas cumple esas condiciones.'),
  (14, 'FAMILIAR', '9.2.6', 'El 100% de las camas revisadas es suave, tiene suficiente material, no deja ver el suelo, es de fácil limpieza y desinfección, no tiene elementos que lesionen a los animales y no huele a amoniaco.', 'Entre el 70% y el 99% de las camas revisadas cumple esas condiciones.', 'Entre el 40% y el 69% de las camas revisadas cumple esas condiciones.', 'Menos del 40% de las camas revisadas cumple esas condiciones.'),
