  (15, 'FAMILIAR', '9.2.7', 'El 100% de los corrales tiene iluminación que permite inspeccionar todos los animales y áreas.', 'Entre el 70% y el 99% de los corrales tiene iluminación que permite inspeccionar todos los animales y áreas.', 'Entre el 50% y el 69% de los corrales tiene iluminación que permite inspeccionar todos los animales y áreas.', 'Menos del 49% de los corrales tiene iluminación que permite inspeccionar todos los animales y áreas.'),
  (16, 'PRODUCTIVO', '7.2.8', 'El 100% de los corrales tiene ventilación que evita la concentración de olores.', 'Entre el 70% y el 99% de los corrales tiene ventilación que evita la concentración de olores.', 'Entre el 50% y el 69% de los corrales tiene ventilación que evita la concentración de olores.', 'Menos del 49% de los corrales tiene ventilación que evita la concentración de olores.'),
