  (17, 'PRODUCTIVO', '7.3.1', 'Menos del 3% de los animales presenta secreción nasal o tos.', 'Entre el 4% y el 7% de los animales presenta secreción nasal o tos.', 'Entre el 8% y el 10% de los animales presenta secreción nasal o tos.', 'Más del 10% de los animales presenta secreción nasal o tos.'),
  (17, 'FAMILIAR', '9.3.1', 'Menos del 3% de los animales presenta secreción nasal o tos.', 'Entre el 4% y el 7% de los animales presenta secreción nasal o tos.', 'Entre el 8% y el 10% de los animales presenta secreción nasal o tos.', 'Más del 10% de los animales presenta secreción nasal o tos.'),
